mapper.select:
SELECT acm.id, acm.session_id AS sessionId, acm.role, acm.content, acm.created_at AS createdAt FROM ai_chat_message acm WHERE 1 = 1
AND acm.session_id = #{aiChatMessage.sessionId}
AND acm.role = #{aiChatMessage.role}
AND acm.content LIKE CONCAT('%',#{aiChatMessage.content},'%')
ORDER BY acm.created_at DESC
